mapper.select:
SELECT studentId, name, password, money, status
FROM studentCard
WHERE studentId = #{studentId}

SELECT money
FROM studentCard
WHERE studentId = #{studentId}

mapper.update:
UPDATE studentCard
SET money = money + #{amount}
WHERE studentId = #{studentId}
  AND status = 'ACTIVE'

UPDATE studentCard
SET password = #{password}
WHERE studentId = #{studentId}

UPDATE studentCard
SET money = money - #{amount}
WHERE studentId = #{studentId}
  AND status = 'ACTIVE'
  AND money >= #{amount}
